// Parse blockchain sync message from RabbitMQ
const raw = $input.item.json;

const audit_record_id = raw.audit_record_id;
const correlation_id = raw.correlation_id;
const event_type = raw.event_type;
const reference_table = raw.reference_table;
const reference_id = raw.reference_id;
const token_transaction_id = raw.token_transaction_id || null;
const retry_count = raw.retry_count || 0;

if (!audit_record_id) {
  throw new Error(`Invalid blockchain sync message: missing audit_record_id`);
}

return {
  json: {
    audit_record_id,
    correlation_id,
    event_type,
    reference_table,
    reference_id,
    token_transaction_id,
    retry_count,
    received_at: new Date().toISOString()
  }
};

// Evaluate sync result
const response = $input.item.json;
const statusCode = $input.item.json?.statusCode || 200;

const audit_record_id = $('Parse Sync Message').item.json.audit_record_id;
const correlation_id = $('Parse Sync Message').item.json.correlation_id;

if (response.success) {
  return {
    json: {
      outcome: 'confirmed',
      audit_record_id,
      correlation_id,
      cosmos_tx_hash: response.cosmos_tx_hash || null,
      processed_at: new Date().toISOString()
    }
  };
}

if (response.skipped) {
  return {
    json: {
      outcome: 'skipped',
      audit_record_id,
      correlation_id,
      reason: response.reason,
      processed_at: new Date().toISOString()
    }
  };
}

// circuit_breaker → reject message so RabbitMQ requeues
if (response.circuit_breaker) {
  throw new Error(`Circuit breaker: Cosmos node unreachable for ${audit_record_id}`);
}

// Failed but not exhausted → ack (status already updated in DB)
return {
  json: {
    outcome: response.status === 'exhausted' ? 'exhausted' : 'failed',
    audit_record_id,
    correlation_id,
    error: response.error,
    retry_count: response.retry_count,
    processed_at: new Date().toISOString()
  }
};
